#include "search.h"
#include "stdlib/stats/base/dists/poisson/cdf.h"

double stdlib_base_dists_poisson_search_left( double x, double p, double lambda ) {
    while ( x > 0.0 && stdlib_base_dists_poisson_cdf( x - 1.0, lambda ) >= p ) {
        x -= 1.0;
    }
    return x;
}

double stdlib_base_dists_poisson_search_right( double x, double p, double lambda ) {
    while ( stdlib_base_dists_poisson_cdf( x, lambda ) < p ) {
        x += 1.0;
    }
    return x;
}
